<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialAutenticatorAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialAutenticatorAccessor trait.
 *
 * Covers null default, string/VO assignment via withAutenticator,
 * getAutenticator/autenticator accessors, and isAutenticatorChanged with/without original.
 */
class UserWebauthnCredentialAutenticatorAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAutenticator creates a new instance with the Autenticator set
     * from a string value, and getAutenticator returns the primitive string.
     */
    public function testWithAutenticatorFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAutenticatorAccessorUnitTest();

        // Act
        $result = $holder->withAutenticator('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAutenticator());
    }
    /**
     * Asserts that withautenticator has access to the value object
     * from a string value, and getAutenticator returns the primitive string.
     */
    public function testWithAutenticatorFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAutenticatorAccessorUnitTest();

        // Act
        $result = $holder->withAutenticator('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->autenticator()->value());
    }
    public function testChangedAutenticator(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAutenticatorAccessorUnitTest()->withAutenticator('one');
        $original = $holder->withAutenticator('one');
        $same = $holder->withAutenticator('one');
        $modified = $holder->withAutenticator('other');

        // Act
        $withSame = $original->isAutenticatorChanged($same);
        $withDiferent = $original->isAutenticatorChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialAutenticatorAccessorUnitTest
{
    use UserWebauthnCredentialAutenticatorAccessor;
}
